def apply_pronunciation(lyrics: str, name: str, respelling: str) -> str:
    """Return lyrics with the name swapped for its phonetic respelling so ACE-Step
    SINGS it correctly. The displayed/saved lyrics keep the real name; only the
    text fed to the singing model is respelled. Case-insensitive whole-word swap."""
    if not name or not respelling or not respelling.strip():
        return lyrics
    pattern = re.compile(re.escape(name.strip()), re.IGNORECASE)
    return pattern.sub(respelling.strip(), lyrics)

def _sync_to_plex(audio_path: Path, metadata: dict) -> None:
    try:
        import appconfig
        from plex_module import sync_file
        conf = {"plex_library_path": appconfig.get("plex_library_path", ""),
                "plex_url": appconfig.get("plex_url", "http://localhost:32400"),
                "plex_token": appconfig.get("plex_token", ""),
                "plex_music_section_id": appconfig.get("plex_music_section_id", ""),
                "auto_scan_on_copy": True}
        sync_file(audio_path, metadata, conf=conf)
    except Exception:
        pass  # Plex sync is optional — never fail the song because of it

def isolate_reference(song_path, work_dir, seconds: int = 30) -> Path:
    """Return a path to the isolated artist vocals (the VC reference)."""
    import source_engine
    clip = _slice_for_reference(song_path, work_dir, seconds)
    try:
        stems = source_engine.separate_stems(clip, device="cuda")
    except Exception:
        stems = source_engine.separate_stems(clip, device="cpu")
    return stems["vocals"]

def clone_dedication(song_path, source_speech, work_dir, diffusion_steps: int = 25) -> Path:
    ref = isolate_reference(song_path, work_dir)
    return convert(source_speech, ref, work_dir, diffusion_steps=diffusion_steps)

